function serializeFacets(rows) {
  if (!Array.isArray(rows) || !isDenseArray(rows)) {
    throw new TypeError();
  }

  const pairs = [];

  for (let i = 0; i < rows.length; i++) {
    const row = rows[i];

    if (!isPlainObject(row) || typeof row.name !== "string") {
      throw new TypeError();
    }

    const values = row.values;
    if (!Array.isArray(values) || !isDenseArray(values)) {
      throw new TypeError();
    }

    for (let j = 0; j < values.length; j++) {
      if (typeof values[j] !== "string") {
        throw new TypeError();
      }

      pairs.push({
        name: percentEncode(row.name),
        value: percentEncode(values[j])
      });
    }
  }

  pairs.sort((a, b) =>
    a.name < b.name ? -1 :
    a.name > b.name ? 1 :
    a.value < b.value ? -1 :
    a.value > b.value ? 1 : 0
  );

  return pairs.map(pair => `${pair.name}=${pair.value}`).join("&");
}

function isDenseArray(value) {
  for (let i = 0; i < value.length; i++) {
    if (!Object.prototype.hasOwnProperty.call(value, i)) {
      return false;
    }
  }
  return true;
}

function isPlainObject(value) {
  if (value === null || typeof value !== "object") {
    return false;
  }

  const prototype = Object.getPrototypeOf(value);
  return prototype === Object.prototype || prototype === null;
}

function percentEncode(value) {
  return encodeURIComponent(value).replace(/[!'()*]/g, character =>
    `%${character.charCodeAt(0).toString(16).toUpperCase()}`
  );
}
